'use strict';
const {course}=require('./backend-helper');
const setup='import subprocess, tempfile\nfrom pathlib import Path\nwith tempfile.TemporaryDirectory() as directory:\n    root = Path(directory)\n    def git(*args, check=True):\n        return subprocess.run(["/usr/bin/git", "-C", directory, *args], check=check, capture_output=True, text=True)\n    git("init", "-b", "main")\n    git("config", "user.name", "Synthetic Author")\n    git("config", "user.email", "synthetic@example.invalid")\n    git("config", "commit.gpgsign", "false")\n';
const example=body=>setup+body.split('\n').map(l=>'    '+l).join('\n');
const L=[];
L.push({id:'git-snapshots',comp:'m1.c1',title:'Build commits from a deliberate staging snapshot',before:'Programming Foundations introduces files and change. These examples create disposable repositories and never touch the application checkout.',intro:'A team changes a portal validation rule and its help text. Git records snapshots, but a commit includes the index state rather than every unsaved idea in the working directory. Understanding working tree, index and commit prevents unrelated edits from slipping into a review.',sections:[['Distinguish the three states','The working tree contains current files. The index, often called the staging area, records the content selected for the next commit. A commit records that snapshot with parent information and metadata. git add updates the index to the chosen file content at that moment; later edits are not automatically added.','Use git status and the two relevant diffs before committing: git diff shows unstaged changes, while git diff --staged shows the staged patch relative to the current commit. A clean staged diff is not proof of correctness; it explains what reviewers will receive.'],['Keep one reviewable purpose','A focused commit should tell one coherent story such as validating an enrollment deadline. Include the relevant tests and avoid mixing unrelated formatting, credentials or generated dumps. The file need not be staged as a whole: selective hunk staging can separate independent changes when done carefully.','The fixture stages one version of a file and then edits the working tree. Its two comparisons prove the states differ. This does not commit real student data or demonstrate any remote review policy.']],problem:'Observe that a post-staging edit is absent from the index.',steps:['Create and stage an initial fixture version.','Edit the same file without adding again.','Read the index and working tree independently.'],code:example('target = root / "policy.txt"\ntarget.write_text("first\\n")\ngit("add", "policy.txt")\ntarget.write_text("second\\n")\nprint(git("show", ":policy.txt").stdout.strip())\nprint(target.read_text().strip())'),expect:'first\nsecond',result:'The index still contains first while the working file contains second. The next commit would use the staged version unless it is updated.',mistakes:['git add is not a permanent subscription to later file edits.','Staging all files blindly can include unrelated or sensitive content.'],takeaways:['Inspect the staged patch before recording a snapshot.','Keep working-tree changes separate from the intended commit.'],refs:['commit','diff'],q:[
['E','Which state supplies a normal Git commit’s file snapshot?','The index','Every open editor buffer','Every remote branch','Only unstaged files','The index holds the selected content for the next snapshot.','Unsaved buffers are not Git objects.|Remotes are separate refs.|Unstaged content is not selected automatically.'],
['E','A file is edited after git add. Is the later edit automatically staged?','No, add must update it','Yes, add watches forever','Yes, if the editor stays open','Only after changing the filename','Staging records content at a point in time rather than watching future edits.','Git add is not a watcher.|Editor state does not update the index.|Renaming is unrelated.'],
['M','Which command inspects the patch selected for the next commit?','git diff --staged','git log --oneline','git branch --list','git remote -v','The staged diff compares the index with the current committed snapshot.','History does not show the selected uncommitted patch.|Branch listing shows names.|Remote listing shows endpoints.'],
['M','A commit mixes an enrollment fix with unrelated theme changes. What improves review?','Separate coherent changes','Remove the regression test','Hide half the diff','Commit every local file','Focused commits make purpose and risk easier to assess.','Relevant tests belong with the fix.|Hiding changes harms review.|Local presence does not imply relevance.'],
['H','git diff is empty but git diff --staged has changes. What follows?','The index differs from HEAD','The repository has no changes','The remote already deployed','Every file is untracked','Unstaged comparison can be clean while the staged snapshot differs from the current commit.','The staged diff establishes a change.|Deployment is a separate action.|Tracked files can have staged edits.'],
['M','What does git status help summarize before commit?','Tracked and untracked state','All production database rows','The correctness of every test','The deployment’s live version','Status reports repository working/index state, not application correctness or production state.','Git status does not query data.|Tests require execution.|Remote deployment is separate.'],
['H','A developer stages a password dump accidentally. What should happen before commit?','Unstage and secure the file','Commit then hide the filename','Push it to a private branch first','Assume staging encrypts it','Remove unintended sensitive content from the proposed snapshot and handle it under local security policy.','A hidden name does not remove contents.|Pushing spreads exposure.|The index is not encryption.'],
['M','Why inspect both unstaged and staged diffs?','They compare different states','They always contain identical text','They both query production','They replace code review','The two comparisons reveal selected versus still-unselected edits.','Staging can make them differ.|They inspect local repository state.|Review remains necessary.'],
['H','A partially staged file passes a test against the working tree. What mismatch should be considered?','The commit may contain different code','Git ran the staged tests automatically','The remote guarantees equivalence','The index cannot contain partial changes','Tests may exercise unstaged edits absent from the selected commit.','Git does not run tests automatically by default.|Remotes do not prove equivalence.|Partial staging is supported.'] ]});
L.push({id:'git-branches',comp:'m1.c1',title:'Merge branches and resolve content conflicts deliberately',before:'Understand commit snapshots and inspect local modifications before switching branches.',intro:'Two engineers update the same registration rule from a shared starting commit. Branches let both histories exist, while merging must reconcile their changes. A conflict is a request for a human decision about the combined meaning, not a command to keep whichever text appears first.',sections:[['A branch is a moving reference','A local branch points to a commit; new commits normally move the checked-out branch forward. Creating a branch is cheap because it does not copy the entire repository directory. Switching changes the checked-out snapshot, subject to protection against overwriting local changes.','A fast-forward merge can move a reference when one history is an ancestor of the other. Divergent histories may require a merge commit. The appropriate workflow can choose linear or explicit merge history, but both must preserve intended changes and understandable review context.'],['Resolve semantics, then stage and test','When the same content cannot be combined automatically, inspect the base and both sides. Remove conflict markers only after choosing the correct combined requirement. git add records the resolution in the index; it does not establish that the behavior is correct. Run relevant tests and inspect the final diff before completing the merge.','If the merge should not proceed, use the documented abort operation and confirm working-tree state. Do not solve a shared-history problem with a destructive reset unless the consequences and authorization are understood. The fixture demonstrates a nonconflicting divergent merge in one temporary repository.']],problem:'Merge independent feature and documentation commits without contacting a remote.',steps:['Record a shared base and create a feature branch.','Make independent commits on feature and main.','Merge and verify that both files remain.'],code:example('(root / "base.txt").write_text("base")\ngit("add", "."); git("commit", "-m", "Record base")\ngit("switch", "-c", "feature")\n(root / "feature.txt").write_text("feature")\ngit("add", "."); git("commit", "-m", "Add feature")\ngit("switch", "main")\n(root / "guide.txt").write_text("guide")\ngit("add", "."); git("commit", "-m", "Add guide")\ngit("merge", "--no-edit", "feature")\nprint(sorted(p.name for p in root.glob("*.txt")))'),expect:"['base.txt', 'feature.txt', 'guide.txt']",result:'The merge retains both independent changes. This example does not claim that textual auto-merge proves semantic compatibility.',mistakes:['A successful textual merge can still combine incompatible business rules.','Choosing one conflict side blindly can silently discard intended work.'],takeaways:['Treat branch pointers and commit ancestry separately from file content.','Validate the combined behavior after resolving a conflict.'],refs:['branch','merge','switch'],q:[
['E','What does a local branch name normally reference?','A commit','A full copied filesystem','A production database','A mandatory remote server','A branch is a movable reference into commit history.','Creating a branch does not copy a directory tree.|Branches do not identify database instances.|Local branches can exist without remotes.'],
['E','What must be removed from a resolved conflicted file?','Conflict markers','Every test assertion','Both intended changes','The repository metadata','Markers are temporary resolution syntax and must not remain as unresolved source content.','Tests should remain meaningful.|The correct resolution may combine both changes.|Deleting Git metadata is not resolution.'],
['M','When can Git fast-forward a target branch?','Its tip is an ancestor','Both branches have no files','A remote is always online','Every commit message matches','Fast-forwarding advances a reference along existing descendant history.','File count is unrelated.|It can be entirely local.|Messages do not determine ancestry.'],
['M','After editing a conflicted file, what records the chosen resolution?','Staging the resolved content','Renaming the terminal window','Fetching an unrelated remote','Only deleting the error log','The index records the resolved version for the merge commit.','Terminal naming is irrelevant.|Fetching does not stage a resolution.|Logs do not select file content.'],
['H','A merge completes automatically but changes two interacting validation rules. What is still needed?','Semantic regression checks','A claim that auto-merge proves safety','Only a shorter branch name','Immediate publication without review','Textual compatibility does not prove the combined behavior meets requirements.','Git cannot infer every business invariant.|Names do not test behavior.|Publication needs its own decision.'],
['M','Two teams edit different files from one base. What can a merge preserve?','Both independent histories','Only whichever branch was created first','Only the newest file alphabetically','No parent information','A merge can retain changes from divergent branches and record their ancestry.','Creation order does not select one history.|Alphabetical order is irrelevant.|Merge commits record parent relationships.'],
['H','A conflict resolution keeps one side solely because it is newer. What is missing?','Combined requirements','A newer terminal version','A larger editor font','A remote cache refresh','The correct choice depends on the required semantics, not timestamp preference alone.','Terminal versions do not decide meaning.|Fonts are irrelevant.|Remote caching is unrelated.'],
['M','A merge was started in error and should be abandoned. What action fits its documented workflow?','Abort the merge safely','Delete the entire project','Force-push an unrelated branch','Commit unresolved markers','A merge abort can restore the pre-merge state subject to documented working-tree limits.','Deleting the project is unnecessary.|Force-pushing does not resolve local state.|Unresolved markers are not a valid completion.'],
['H','Why check local changes before switching branches?','To avoid overwriting work','To encrypt the branch name','To guarantee deployment succeeds','To remove all future conflicts','Switching can be blocked or complicated by local edits that would be overwritten.','Names are not encrypted by status checks.|Deployment is separate.|Future edits can still conflict.'] ]});
L.push({id:'git-history',comp:'m1.c2',title:'Inspect history and choose safe undo operations',before:'Know snapshots, branch ancestry and the index before using undo commands.',intro:'A reviewed commit introduced an incorrect deadline in a shared branch. Fixing it should preserve colleagues’ history and explain why the change was undone. Git offers several operations with very different effects on references, files and existing collaborators.',sections:[['Inspect before changing history','git log shows commit history; git show inspects a selected commit and its patch; git diff compares chosen states. Identify the actual change and the branch it reached before deciding how to undo it. A merge history is a graph, not simply a list of filenames sorted by time.','Use the repository’s review context and tests to distinguish the defect from neighboring valid changes. A broad reversal can remove a later fix if the dependency is ignored. Reflogs can help locate recently moved local references, but they are local recovery records with expiration, not an unlimited backup strategy.'],['Separate restore, revert and reset','git restore can copy selected file content into the working tree or index, depending on flags. git revert creates a new commit that reverses a prior change, which is usually easier to collaborate with after publication. git reset can move references and, in stronger modes, alter the index and working tree; it can discard work.','Do not rewrite shared history merely to make a graph look tidy. If a local unpublished correction is appropriate, inspect the exact consequences first. The fixture uses revert on an ordinary commit and proves history grows while the earlier file content returns. It never alters the application repository.']],problem:'Undo a shared-style content change using a new reversing commit.',steps:['Commit two versions of a synthetic policy.','Revert the second commit in the temporary repository.','Compare file content and commit count afterward.'],code:example('target = root / "policy.txt"\ntarget.write_text("original\\n")\ngit("add", "."); git("commit", "-m", "Record original rule")\ntarget.write_text("changed\\n")\ngit("add", "."); git("commit", "-m", "Change rule")\ngit("revert", "--no-edit", "HEAD")\nprint(target.read_text().strip())\nprint(git("rev-list", "--count", "HEAD").stdout.strip())'),expect:'original\n3',result:'The file is restored through a third commit; the original change remains in history. Reverting a merge requires additional parent reasoning not demonstrated here.',mistakes:['A hard reset can discard local work instead of merely creating a correction.','Reflog availability is not a substitute for a backup or shared branch.'],takeaways:['Choose undo by publication state and intended effects.','Prefer an explanatory new correction for shared history.'],refs:['log','show','restore','revert','reset'],q:[
['E','Which command normally adds a commit reversing an earlier change?','git revert','git status','git remote -v','git branch --list','Revert records a new inverse change rather than deleting the original commit from shared history.','Status reports state.|Remote listing reports endpoints.|Branch listing reports names.'],
['E','Which command inspects one commit and its patch?','git show','git init','git remote add','git switch -c','Show displays selected object information and usually its patch for a commit.','Init creates a repository.|Remote add records a remote.|Switch creates or changes a branch.'],
['M','Why is revert often suitable after colleagues fetched a change?','It preserves shared history','It erases everyone’s clones','It guarantees no conflicts','It removes all review needs','A new inverse commit avoids requiring collaborators to replace published ancestry.','Other clones are not erased.|Inverse patches can conflict.|Review and testing still matter.'],
['M','What can a hard reset affect beyond the branch reference?','Index and working files','Every remote automatically','The production database schema','All other engineers’ editors','Hard reset can replace tracked index/working-tree content and discard local changes.','Remotes require separate updates.|Git does not migrate a database by itself.|Editors on other machines are separate.'],
['H','A local reflog entry helped recover a moved commit. What limitation remains?','Entries can expire locally','It is a permanent global backup','Every colleague has identical entries','It records all untracked file contents','Reflogs are local reference movement records with retention limits.','They are not guaranteed permanent backups.|Different clones have different movements.|Untracked files are not automatically Git objects.'],
['M','What should happen before undoing a broad commit?','Inspect its relevant patch','Delete all later work','Assume every line is wrong','Rename the branch to fixed','Understand scope and dependencies before selecting a corrective operation.','Later valid work should be preserved.|A commit can mix valid and defective changes.|Naming does not undo content.'],
['H','A revert of a feature removes a later dependent behavior. What was missed?','Change dependency analysis','The need for longer hashes','The remote repository color','The test filename extension','Inverse changes must be assessed against subsequent dependent work.','Hash length does not explain semantic dependencies.|Color is irrelevant.|Extensions do not settle behavior.'],
['M','Which action can discard an unstaged tracked-file edit by copying committed content?','A suitable git restore','Only git log','Only git remote -v','Only git branch --list','Restore can replace selected working-tree content, so inspect before using it.','History display does not replace files.|Remote listing does not change content.|Branch listing is read-only.'],
['H','A history rewrite is proposed solely to hide a bug that reached a shared branch. What is safer for ordinary correction?','A reviewed follow-up change','An unannounced forced update','Deleting colleague branches','Removing the audit trail entirely','An explicit correction preserves collaboration and explains the changed behavior.','Forced shared rewrites can disrupt others.|Their branches should be preserved.|Auditability supports understanding.'] ]});
L.push({id:'git-review',comp:'m2.c1',title:'Prepare pull requests that reviewers can evaluate',before:'Use focused commits and inspect the combined diff against the intended base.',intro:'A pull request for a student dashboard should explain the trigger, resulting behavior and evidence. Reviewers need a concrete patch and useful tests, not a long narrative of every abandoned idea. Git commits carry the changes; the hosting platform supplies the pull-request discussion and merge controls.',sections:[['Explain the problem and resulting behavior','State what user action currently fails and how the patch changes that outcome. Include the relevant validation and any remaining limitations. Keep the diff focused enough to review without hiding necessary supporting changes. A screenshot is useful for layout; it cannot prove server authorization or assessment scoring.','Link a relevant requirement or issue when available, and describe migrations or compatibility risks if the change has them. Never paste production secrets, private student records or answer keys into a public description. Use synthetic examples to explain behavior.'],['Review the final patch and respond with evidence','Reviewers should examine logic, edge cases, maintainability and tests. A request for clarification is not a rejection of the author; explain the tradeoff or make the correction. After changes, rerun the checks affected and ensure required review applies to the final content under the platform’s policy.','The fixture creates a feature commit and compares it with the base using Git. It does not create a real pull request or enforce GitHub permissions. Hosted approval, stale-review dismissal and protected-branch settings are platform controls that must be configured and inspected separately.']],problem:'Build a concise local review inventory from the actual branch difference.',steps:['Create a base file and feature branch.','Commit one intended change.','List changed files relative to the base branch.'],code:example('(root / "deadline.txt").write_text("old")\ngit("add", "."); git("commit", "-m", "Record deadline baseline")\ngit("switch", "-c", "deadline-fix")\n(root / "deadline.txt").write_text("new")\ngit("add", "."); git("commit", "-m", "Apply registration deadline rule")\nprint(git("diff", "--name-only", "main...HEAD").stdout.strip())'),expect:'deadline.txt',result:'The review diff identifies the changed file from the branch merge base. No hosted pull request or approval state was created.',mistakes:['A screenshot alone cannot substantiate backend correctness.','An approval before later changes may not satisfy the final platform policy.'],takeaways:['Lead a review description with observable before/after behavior.','Distinguish Git content from hosting review permissions.'],refs:['diff','workflows'],q:[
['E','What should a useful pull-request description lead with?','The problem and new behavior','Every abandoned editor action','The author’s private password','Only the number of changed lines','Reviewers need to understand the concrete behavior and purpose of the final patch.','Chronology often obscures the outcome.|Secrets must not be included.|Line count does not explain purpose.'],
['E','Which system normally supplies pull-request approvals?','The hosting platform','A Git blob automatically','The Python interpreter','A local file extension','Review approvals are hosted workflow metadata rather than automatic Git object behavior.','Blobs store content.|Python does not grant repository approval.|Extensions do not enforce review.'],
['M','Which evidence supports a responsive layout change?','Relevant viewport screenshots','Only a database schema dump','A claim that all code compiles','A raw session cookie','Screenshots at intended widths show the rendered layout being changed.','Schema data does not show layout.|Compilation does not verify rendering.|Credentials are unnecessary.'],
['M','Which evidence supports an authorization correction?','Server-side permission tests','Only a green button screenshot','Only a new stylesheet','Only a longer PR title','The access decision executes on the server and needs direct behavioral evidence.','Appearance does not enforce permissions.|Styles do not authorize.|Titles are not test evidence.'],
['H','New commits arrive after an approval. What must the team inspect?','Final review policy and checks','Only the original approval emoji','Only the initial screenshot','The author’s keyboard settings','Required review/check policies must apply to the final proposed state.','An old reaction may not satisfy policy.|Earlier images may be stale.|Keyboard settings are unrelated.'],
['M','What should a review note disclose about an untested native race?','The evidence limit','A fabricated passing test','An assertion it cannot happen','A hidden production experiment','Reviewers need accurate limits so they can judge remaining risk.','Invented results are misleading.|Absence of testing is not impossibility.|Unauthorized live testing is unnecessary.'],
['H','A PR summary describes an earlier approach that was removed. What should change?','Describe the final patch','Keep obsolete claims for volume','Delete all validation details','Mark it reviewed automatically','The description must help reviewers assess the implementation they will merge.','Obsolete claims confuse scope.|Relevant validation remains useful.|Description edits do not grant approval.'],
['M','A reviewer asks why a fallback is safe. What response is useful?','The contract and evidence','Only a statement of confidence','A copied private user record','A claim that tests are annoying','Explaining invariants, checks and limitations makes the tradeoff reviewable.','Confidence is not evidence.|Private data is unnecessary.|Dismissing checks does not answer the question.'],
['H','A diff is too large because it mixes feature work and generated logs. What improves review?','Remove unrelated artifacts','Hide the large files from view','Declare all files equivalent','Skip the reviewer entirely','Keep necessary implementation/test changes and exclude accidental generated material.','Hidden files remain part of the patch.|Files differ in purpose and risk.|Review remains useful.'] ]});
L.push({id:'git-branch-policy',comp:'m2.c2',title:'Choose a branching strategy from delivery constraints',before:'Know merge ancestry and the distinction between local Git and hosting controls.',intro:'A small SaaS team ships daily while a mobile team maintains several supported releases. The same branch convention need not fit both. Choose a strategy that makes integration, release support and recovery understandable rather than copying a diagram without its assumptions.',sections:[['Match branch lifetime to coordination cost','Short-lived feature branches integrate frequently and reduce long divergence, provided automated checks and review support safe changes. Trunk-based development emphasizes frequent integration, often with feature flags to separate code integration from public availability. Flags themselves need testing and eventual cleanup.','Release branches can support selected fixes for a maintained version while main continues forward. Long-lived environment or team branches can drift, making merges and duplicated fixes expensive. Record how fixes propagate to every supported line and who owns release selection.'],['Protect delivery invariants rather than branch names','A strategy should specify the trusted integration branch, required checks, review, version/tag policy and emergency corrections. Branch names alone do not enforce any of these rules. Select a workflow that the team and tooling can actually operate consistently.','The fixture shows a fix deliberately copied to a release branch through cherry-pick. That creates a distinct commit for the same patch, so later merge history needs care. It does not recommend copying every change or bypassing review.']],problem:'Apply a targeted fix to a maintenance branch without importing an unrelated feature.',steps:['Create release and main from a shared base.','Commit a fix on main.','Cherry-pick only that fix into release and inspect the result.'],code:example('(root / "version.txt").write_text("base")\ngit("add", "."); git("commit", "-m", "Record shared version")\ngit("branch", "release")\n(root / "fix.txt").write_text("targeted fix")\ngit("add", "."); git("commit", "-m", "Correct parser boundary")\nfix = git("rev-parse", "HEAD").stdout.strip()\ngit("switch", "release")\ngit("cherry-pick", fix)\nprint((root / "fix.txt").read_text())\nprint(git("branch", "--show-current").stdout.strip())'),expect:'targeted fix\nrelease',result:'The maintenance branch receives the selected patch. This does not verify release testing, conflict resolution or hosted branch permissions.',mistakes:['A release branch without a fix-propagation policy can leave supported versions vulnerable.','Feature flags do not remove the need to test both relevant states.'],takeaways:['Choose a strategy from release and support needs.','Document integration, backport and emergency rules explicitly.'],refs:['workflows','branch','cherry'],q:[
['E','What commonly reduces merge drift?','Frequent integration','Never updating feature branches','Separate copies outside Git','Ignoring the shared base','Integrating often limits the distance between active histories.','Long divergence increases coordination cost.|Untracked copies lose history.|The base informs merge reasoning.'],
['E','What is a release branch commonly used for?','Maintaining a supported line','Storing production passwords','Replacing every feature branch','Avoiding all tests','A maintenance line can receive selected compatible corrections.','Secrets do not belong in history.|Workflow needs vary.|Maintenance still needs validation.'],
['M','What does a feature flag separate when used appropriately?','Integration from availability','Authentication from every permission','Git objects from encryption','Tests from correctness requirements','A flag can allow code integration while controlling whether users receive a feature.','Permissions still need enforcement.|Flags are not encryption.|Both relevant states need tests.'],
['M','A fix reaches main but not an affected release. What policy is missing?','Fix propagation','Only branch color conventions','Only editor indentation','Only commit author initials','Supported lines need explicit decisions about applicable fixes.','Colors do not propagate patches.|Indentation is unrelated.|Initials do not maintain releases.'],
['H','What is a maintenance risk of many long-lived team branches?','Divergence and repeated fixes','Automatic conflict elimination','Guaranteed smaller reviews','Identical supported versions','Long-lived isolated work increases integration and synchronization costs.','Conflicts can grow.|Reviews may become larger.|Versions can diverge.'],
['M','What does cherry-pick generally apply?','A selected commit’s change','Every remote branch name','The entire repository database','All later release tags','Cherry-pick reapplies selected changes onto the current history.','Names are not the selected patch.|It does not copy every object as behavior.|Later tags are not all applied.'],
['H','A team uses trunk-based development without reliable checks or rollback planning. What should be reviewed?','The supporting delivery controls','Only the name trunk','A requirement to never review','Whether Git supports files','A branching label cannot compensate for missing validation and recovery controls.','Naming alone is not the issue.|Review can remain important.|Git file support is unrelated.'],
['M','What should determine whether to keep a release branch?','Support and delivery needs','A random calendar color','The number of team emojis','A copied diagram alone','A branch has ongoing coordination cost that should match real maintenance requirements.','Colors do not define support.|Emojis are irrelevant.|A diagram needs contextual assumptions.'],
['H','A flag is removed after rollout. What should the cleanup preserve?','The intended final behavior','Every obsolete branch forever','Unused conditional paths','No regression checks','Flag cleanup should simplify code while preserving the deployed requirement.','Obsolete branches need lifecycle decisions.|Dead conditionals add confusion.|Relevant tests should remain.'] ]});
L.push({id:'git-protection',comp:'m2.c1',title:'Align protected branches, required checks and final review',before:'Understand pull-request review and the chosen integration strategy.',intro:'A repository can display green checks while an important job never ran. Protection needs an explicit policy about which checks and reviewers are required, what state they evaluated and who may bypass them. Git itself stores history; hosting settings decide whether a proposed update is allowed.',sections:[['Treat check identity and scope as part of the policy','A required status must come from the intended workflow and apply to the commit being merged. Check names, permissions, trusted execution context and skipped-job behavior matter. A passing unit suite cannot stand in for a missing migration or permission check simply because both indicators are green.','Review rules may require designated ownership, fresh approval after changes and no author self-approval under the team’s policy. Restrict direct writes and bypass rights appropriately, then verify the actual configuration. A branch named protected has no special native Git enforcement by its name.'],['Keep emergency paths explicit and auditable','Urgent fixes still need the smallest useful validation, an accountable decision and a follow-up review where policy permits an emergency bypass. Do not silently weaken permanent controls to make a merge pass. Record why the exception was necessary and restore any time-bounded change.','The local fixture demonstrates a content-changing commit has a different identity from its reviewed predecessor. It cannot prove GitHub required-status enforcement. Actual hosted controls must be inspected through the authorized platform settings.']],problem:'Show why approval of one commit cannot automatically describe changed content.',steps:['Commit a baseline candidate.','Change the candidate and create another commit.','Compare object identities without printing their hashes.'],code:example('target = root / "candidate.txt"\ntarget.write_text("reviewed")\ngit("add", "."); git("commit", "-m", "Prepare review candidate")\nfirst = git("rev-parse", "HEAD").stdout.strip()\ntarget.write_text("changed")\ngit("add", "."); git("commit", "-m", "Change review candidate")\nsecond = git("rev-parse", "HEAD").stdout.strip()\nprint(first != second)\nprint(git("rev-list", "--count", "HEAD").stdout.strip())'),expect:'True\n2',result:'The proposed state changed identity. Whether earlier approval is dismissed depends on the separately configured hosting policy.',mistakes:['A green optional job is not proof every required check ran.','Permanent bypasses can undermine otherwise careful review settings.'],takeaways:['Tie validation and review to the final proposed state.','Inspect actual platform rules rather than infer protection from names.'],refs:['workflows','commit'],q:[
['E','Does naming a branch protected enforce review in native Git?','No, naming is insufficient','Yes, the name is a built-in rule','Only if it contains numbers','Only with a longer description','Hosting or server policy must enforce updates; names alone do not.','Git does not reserve that name for approval.|Digits do not grant policy.|Descriptions do not enforce updates.'],
['E','What should a required check describe?','The intended evaluated state','Any old passing commit','Only the author’s opinion','A screenshot of another branch','Checks must correspond to the relevant proposed content and required scope.','Old success can be stale.|Opinion is not execution.|Another branch may differ.'],
['M','A required job is skipped but another optional job is green. What needs inspection?','Required-status policy','Only badge color preferences','Whether the PR title is short','The editor theme','The policy must establish that the intended required work actually satisfied the merge rule.','Color alone does not establish scope.|Title length is unrelated.|Themes do not execute jobs.'],
['M','Who should have bypass rights?','Only appropriate authorized roles','Every anonymous reader','Any pull-request author by default','Every student account','Bypass authority changes the effective protection boundary and must be scoped.','Anonymous access should not update protected history.|Authors need not bypass their review.|Student status is not repository authority.'],
['H','A new commit arrives after the only test run. What should be evaluated before merge?','Checks for the final state','Only the earlier green badge','Only the old approval text','The author’s local editor state','New content can invalidate earlier evidence and must satisfy configured final-state requirements.','Old checks may not cover new content.|Text alone is not execution.|Editor state is not the proposed commit.'],
['M','An emergency bypass is permitted by policy. What should it retain?','Accountability and follow-up','Permanent silent disablement','Unrecorded direct pushes','A claim that tests are unnecessary','An exception should be explicit, scoped and reviewable under the authorized policy.','Silent permanent weakening exceeds the exception.|Unrecorded actions undermine auditability.|Relevant validation still matters.'],
['H','A workflow can be edited by the same unreviewed patch it validates. What trust question matters?','Who controls trusted checks','Only workflow indentation','Only the branch suffix','The number of comments','The integrity and permissions of the evaluation path affect what a passing status means.','Valid formatting is not enough.|Suffixes do not establish trust.|Comment count does not protect execution.'],
['M','What should reviewers verify instead of assuming all protections are active?','The actual server settings','Only a branch-name convention','Only a README promise','Only a local Git alias','Effective enforcement resides in configured server/hosting rules.','Conventions are not enforcement.|Promises can be stale.|Local aliases cannot bind other writers.'],
['H','A permanent admin bypass is used for ordinary work. What should be reassessed?','The effective review boundary','Only the test output colors','Whether commits have hashes','The maximum title length','Routine bypass can defeat the controls that ordinary contributors must satisfy.','Colors do not restrict updates.|All commits have identities.|Title length is not the trust boundary.'] ]});
L.push({id:'git-ignore',comp:'m3.c1',title:'Prevent accidental credential and private-data commits',before:'Understand staged snapshots and review the full diff before recording it.',intro:'A developer creates a local environment file while testing mail delivery. Keeping it out of the next commit requires more than hiding it in the editor. Ignore rules, safe configuration templates and staged-diff review work together, while real secrets belong in controlled runtime configuration.',sections:[['Know what ignore rules do','A .gitignore rule normally affects untracked files considered by Git discovery. It does not remove a file already tracked in commits, encrypt local content or erase earlier history. Use a nonsecret example configuration to document variable names without recording real values.','Review generated exports, logs, archives and screenshots for personal data as well as credentials. Narrow staging and secret scanning can catch mistakes, but automated scanners have false negatives and positives. Treat every proposed snapshot as content to inspect rather than assuming a scan proves safety.'],['Separate access controls from data minimization','A private repository restricts readers but does not make shared credentials appropriate source content. Collaborators, forks, CI logs and cloned copies expand the places a secret can reach. Use least-privilege runtime credentials with rotation and controlled delivery.','The example writes a clearly synthetic untracked environment file and verifies that Git ignores it while tracking a safe template. It never reads real environment values. The rule demonstrates discovery behavior, not history cleanup or credential revocation.']],problem:'Ignore a local synthetic credential file while staging a safe template.',steps:['Write an ignore rule and nonsecret example file.','Create a synthetic local environment value.','Stage ordinary content and inspect the tracked list.'],code:example('(root / ".gitignore").write_text(".env\\n")\n(root / ".env").write_text("TOKEN=SYNTHETIC-ONLY\\n")\n(root / ".env.example").write_text("TOKEN=configure-at-runtime\\n")\ngit("add", ".")\nprint(git("check-ignore", ".env").stdout.strip())\nprint(git("ls-files", ".env").stdout == "")'),expect:'.env\nTrue',result:'The untracked .env is ignored and absent from the index. Already tracked files require separate handling; no real credential was involved.',mistakes:['Adding a tracked secret to .gitignore does not remove history.','Private repository visibility is not a substitute for secret management.'],takeaways:['Keep runtime values separate from nonsecret templates.','Inspect every staged artifact, including generated files.'],refs:['ignore','lsfiles'],q:[
['E','What does .gitignore normally affect?','Untracked path discovery','Every past commit’s content','Encryption of local files','Automatic credential rotation','Ignore rules help exclude matching untracked paths from ordinary discovery/staging.','History remains unchanged.|Files are not encrypted.|External credentials are not revoked.'],
['E','Which configuration file is suitable to commit?','A nonsecret example template','A real production token dump','A student database backup','A full private session export','Templates can document names and safe placeholders without live credentials or records.','Tokens should not be source content.|Backups contain private data.|Session exports grant sensitive access.'],
['M','An already tracked .env is added to .gitignore. What remains true?','It can remain tracked','Every earlier copy is erased','Its credentials become invalid','It is automatically encrypted','Ignore rules do not retroactively untrack content or remove earlier commits.','Earlier history is unaffected.|Revocation is external to Git.|Ignore does not encrypt.'],
['M','What should a staged archive be checked for?','Secrets and private records','Only its filename length','Only whether it opens','Only its icon color','Generated bundles can contain sensitive data even when their names look harmless.','Length is not content inspection.|A readable archive can still leak data.|Icons do not indicate privacy.'],
['H','A scanner reports no secrets. What conclusion is justified?','No finding within its scope','Proof all content is safe','Permission to publish student data','Guaranteed future credential safety','Automated detection has limited patterns and coverage; manual inspection and policy still matter.','False negatives are possible.|Private records are not authorized by a scan.|Future safety is not established.'],
['M','Why is a private repository still unsuitable for hard-coded shared credentials?','Copies expand exposure','Git cannot store text','Private branches cannot be tested','Every collaborator is anonymous','Clones, CI and authorized readers can spread a credential beyond its intended runtime boundary.','Git can store text, which is the risk.|Private work can be tested.|Reader identity does not remove credential exposure.'],
['H','A pre-commit hook scans secrets only on one developer machine. What limitation remains?','Other writers may bypass it','It enforces every server update','It revokes leaked provider keys','It rewrites all old commits','Local hooks are useful but do not automatically impose policy on every contributor or server path.','Server enforcement is separate.|Provider revocation is external.|Hooks do not erase history by default.'],
['M','Which staging habit reduces accidental unrelated inclusion?','Select and inspect content','Always add every file blindly','Hide untracked paths from view','Commit all downloads','Deliberate staging plus diff inspection makes unintended artifacts easier to catch.','Blind staging increases risk.|Hiding state reduces visibility.|Downloads may contain unrelated data.'],
['H','A local synthetic test value is included in lesson code. What should its presentation make clear?','It has no real authority','It is a reusable production key','It proves the secret store works','It replaces credential rotation','Explicit synthetic values prevent confusion with real operational credentials.','Production keys must not be embedded.|A fixture does not test a real store.|Rotation remains an operational control.'] ]});
L.push({id:'git-secret-response',comp:'m3.c1',title:'Respond to a leaked secret beyond deleting the file',before:'Know the difference between ignoring new files and preserving existing history.',intro:'A provider key accidentally reached a shared branch before a scanner found it. Removing the line from the latest version is necessary, but copies may already exist in history, clones, logs and caches. The first containment question is whether the credential still grants authority.',sections:[['Revoke or rotate the authority','Follow the credential owner’s incident procedure to invalidate or rotate the affected key, review its scope and inspect authorized usage evidence. Do not paste the secret into tickets or chat while reporting it. Preserve safe metadata such as credential identifier, repository revision and exposure window.','A history rewrite may reduce future accidental access but cannot prove that every clone or cache discarded a copy. Coordinate any rewrite with repository owners and collaborators, protect unrelated work, and follow provider/hosting guidance. Never confuse cleaning Git history with external revocation.'],['Verify recovery and prevent recurrence','Update the runtime binding through authorized secret management, confirm the new credential is used, retire any bounded overlap and review access and logs for exposure. Add appropriate ignore rules, safer templates or scanning at the boundary that failed.','The fixture demonstrates why deleting a tracked line does not erase the earlier Git object. It uses a deliberately harmless string and prints only a boolean. It does not rotate a provider key or remove real history, and it should never be run against the application checkout as a cleanup command.']],problem:'Show that an earlier committed value remains in history after the latest file changes.',steps:['Commit a synthetic placeholder in a disposable repository.','Replace it and commit the correction.','Inspect the earlier snapshot without printing the placeholder.'],code:example('target = root / "example.txt"\ntarget.write_text("SYNTHETIC-NO-AUTHORITY")\ngit("add", "."); git("commit", "-m", "Record synthetic fixture")\ntarget.write_text("removed")\ngit("add", "."); git("commit", "-m", "Remove synthetic value")\nold = git("show", "HEAD~1:example.txt").stdout\nprint("SYNTHETIC-NO-AUTHORITY" in old)\nprint(target.read_text())'),expect:'True\nremoved',result:'The old snapshot still contains the harmless fixture even though the working version does not. Real exposure requires external credential containment and authorized incident handling.',mistakes:['Deleting the latest line does not revoke an external key.','History rewriting cannot guarantee removal from every existing copy.'],takeaways:['Contain the credential’s authority before claiming recovery.','Coordinate cleanup and verify runtime rotation without spreading the value.'],refs:['show','workflows'],q:[
['E','A live key was pushed. What action addresses its continuing authority?','Revoke or rotate it','Only delete the latest line','Only rename the branch','Only hide the file in an editor','The external provider must stop accepting the exposed authority under its procedure.','Earlier copies can still work.|Names do not change provider trust.|Editor visibility is unrelated.'],
['E','Does deleting a committed secret from the newest file remove every old copy?','No, history may retain it','Yes, every clone is rewritten','Yes, caches expire instantly','Only if the commit is short','Git retains earlier snapshots and other systems may hold copies.','Other clones are independent.|Cache behavior is not guaranteed.|Message length does not erase objects.'],
['M','What should an incident report include instead of the raw key?','Safe identifying metadata','The full reusable value','Every student’s personal record','The secret in the subject line','Credential identifiers and safe exposure context can support response without redisclosing authority.','Repeating the key spreads risk.|Student data is unrelated.|Subject lines may be widely visible.'],
['M','Why coordinate a history rewrite with collaborators?','It changes shared ancestry','It revokes every provider key','It preserves every old ref automatically','It prevents all future mistakes','Rewriting published history affects clones, branches and ongoing work.','Revocation is external.|Refs need deliberate handling.|Future errors remain possible.'],
['H','After rotation, the service still uses the old key. What recovery evidence is missing?','Runtime binding verification','A shorter README','A new branch color','Only a successful file deletion','The new authority must actually be configured and the old one retired as intended.','README length does not verify runtime.|Colors do not set credentials.|Deletion alone does not change deployment bindings.'],
['M','What should follow initial containment?','Scope and usage review','A claim no copy ever existed','Publication of the key for auditing','Removal of every repository test','Review the exposure window and authorized evidence to assess impact and needed corrections.','Copies may exist.|Publishing increases exposure.|Tests help prevent recurrence.'],
['H','A rewritten repository no longer displays the key. Which claim is still unsupported?','Every copy was destroyed','The latest view omits it','The rewrite changed history','The visible file is clean','Clones, logs and caches may retain copies outside the rewritten repository.','That can be observed locally.|History change is the rewrite’s effect.|A clean current file is within scope.'],
['M','A temporary key overlap is allowed during rotation. What must policy define?','A bounded retirement plan','Indefinite old-key acceptance','No usage verification','A public copy of both keys','Overlap should have explicit lifetime, scope and retirement verification.','Indefinite acceptance preserves exposure.|Verification is important.|Keys should remain controlled.'],
['H','A recurrence was caused by a generated export ignored by a scanner. What prevention targets the cause?','Artifact-specific review controls','Only another random branch','A blanket claim scanners are perfect','Deleting unrelated course content','Controls should address the actual generation/staging boundary and known detection limit.','Random branches do not repair the boundary.|The observed miss disproves perfection.|Unrelated content should be preserved.'] ]});
L.push({id:'git-messages',comp:'m3.c2',title:'Write commit messages that preserve intent and evidence',before:'Use focused patches and understand the final reviewed state.',intro:'Months after a deadline bug is fixed, a maintainer needs to know why equality is rejected rather than only that a comparison changed. A useful commit message records intent and the important constraint so future edits do not accidentally restore the defect.',sections:[['Summarize a coherent result','Use a concise subject that states the concrete change. A body can explain the triggering behavior, why this approach fits and relevant limitations. Explain why a subtle rule exists rather than narrating obvious syntax. Avoid claiming tests passed unless they were actually run and do not imply deployment from a local commit.','Keep secret values and private student examples out of messages: commit metadata travels with clones and can remain after file corrections. Link an issue or safe requirement identifier when it helps reconstruct the decision. The message should describe the final patch, not a removed experiment.'],['Make history useful for review and debugging','Small related commits let a reviewer follow the change and later inspect or revert it with less collateral impact. Teams may squash during integration, so the final combined message should still explain the resulting behavior. A good message cannot rescue unrelated content hidden in a large patch.','The fixture reads a subject and body from a local commit to show they are persistent history data. It does not create a hosting release note or run any test automatically. Validation claims must remain separate evidence, not wishful wording.']],problem:'Record a concrete subject and reason, then inspect both from history.',steps:['Commit a synthetic boundary-policy file.','Include a concise subject and explanatory body.','Read the stored message fields back from the commit.'],code:example('(root / "boundary.txt").write_text("reject equality")\ngit("add", ".")\ngit("commit", "-m", "Reject expiry equality", "-m", "Equality is outside the accepted session interval.")\nprint(git("log", "-1", "--format=%s").stdout.strip())\nprint(git("log", "-1", "--format=%b").stdout.strip())'),expect:'Reject expiry equality\nEquality is outside the accepted session interval.',result:'The subject and reason are stored in history. The message itself is not proof that a session implementation or regression test exists.',mistakes:['A message saying fixed everything communicates no reviewable scope.','Claiming tests passed without running them falsifies the evidence.'],takeaways:['Describe the concrete outcome and the reason for nonobvious choices.','Keep validation and deployment claims accurate and safe.'],refs:['commit','log'],q:[
['E','Which subject better describes an expiry correction?','Reject expiry equality','Stuff updated again','Everything fixed somehow','Temporary random edits','A concrete subject identifies the changed behavior rather than vague activity.','The wording gives no outcome.|Universal claims are implausible.|Temporary activity is not the final result.'],
['E','What belongs in a message body for a subtle boundary rule?','Why the rule is required','A real session credential','Every editor keystroke','An invented passing test count','The reason preserves intent for reviewers and future maintainers.','Credentials must not enter history.|Keystrokes add little lasting value.|Test claims must be actual.'],
['M','The final patch differs from the first experiment. Which message is useful?','One describing the final result','The abandoned approach unchanged','Only the author’s lunch plan','A copied unrelated release note','History should explain the actual committed change and its constraints.','Obsolete descriptions mislead.|Personal plans are unrelated.|Unrelated notes do not describe the patch.'],
['M','Why avoid private student examples in commit messages?','Metadata is widely replicated','Messages are automatically encrypted','Only authors can read history','Messages are deleted after merge','Commit metadata travels in clones and may persist for a long time.','Ordinary messages are not encrypted by Git.|Readers with access can inspect history.|Merging retains commit data or a derived message.'],
['H','A squashed merge combines several related commits. What should the final message preserve?','The resulting behavior and intent','Every obsolete intermediate claim','All accidental secret values','A false deployment assertion','The integrated history entry should remain useful even when intermediate commits are consolidated.','Obsolete claims obscure the result.|Secrets must remain excluded.|Merge does not imply deployment.'],
['M','When may a commit message truthfully say the suite passed?','After the stated checks ran','Whenever the code looks plausible','Only because a linter exists','Before running any tests','Validation claims must reflect executed checks and their actual scope.','Appearance is not execution.|Linter presence is not a passing suite.|Future intention is not a result.'],
['H','A good message accompanies many unrelated changes. What issue remains?','The patch is hard to assess','The message validates all code','The history cannot contain bugs','The tests are unnecessary','Clear prose cannot remove the review cost and risk of unrelated mixed content.','Messages are not execution evidence.|History can contain defects.|Relevant tests still matter.'],
['M','What does a safe issue identifier add to a message?','Traceable requirement context','Automatic user permission','A guarantee of bug-free code','A provider key rotation','A relevant reference can help reconstruct why the change was needed.','Repository messages do not grant app permissions.|References are not correctness proof.|Rotation is an external action.'],
['H','A local commit message says deployed to production although no deploy ran. What should be corrected?','The inaccurate delivery claim','Only the source indentation','The required expiry rule','The test fixture language','Committing and deploying are separate actions and must be reported accurately.','Indentation does not repair a false claim.|The rule may remain correct.|Fixture language is unrelated.'] ]});
const commit='9a2fb147f2c61d0cab52c883e7e26f5b7948e3ed',paths={commit:'git-commit',diff:'git-diff',branch:'git-branch',merge:'git-merge',switch:'git-switch',log:'git-log',show:'git-show',restore:'git-restore',revert:'git-revert',reset:'git-reset',workflows:'gitworkflows',cherry:'git-cherry-pick',ignore:'gitignore',lsfiles:'git-ls-files'};
module.exports=course('git-collaboration',L,Object.entries(paths).map(([id,name])=>{const path='Documentation/'+name+'.adoc';return {id,title:'Git 2.52 documentation: '+name,url:'https://github.com/git/git/blob/'+commit+'/'+path,source:{repo:'git/git',commit,path,verification:'Pinned official Git documentation; synthetic local repositories, no remotes or application history changes. Hosted protections require separate inspection.'}};}));
